import{$}from"chrome://resources/js/util.js";import{BluetoothInternalsHandlerRemote,DebugLogsChangeHandlerRemote}from"./bluetooth_internals.mojom-webui.js";import{Page}from"./page.js";const LOGS_NOT_SUPPORTED_STRING="Debug logs not supported";export class DebugLogPage extends Page{constructor(bluetoothInternalsHandler){super("debug","Debug Logs","debug");this.debugLogsChangeHandler_=null;this.inputElement_=null;this.debugContainer_=$("debug-container");bluetoothInternalsHandler.getDebugLogsChangeHandler().then((params=>{if(params.handler){this.setUpInput(params.handler,params.initialToggleValue)}else{this.debugContainer_.textContent=LOGS_NOT_SUPPORTED_STRING}}))}setUpInput(handler,initialInputValue){this.debugLogsChangeHandler_=handler;this.inputElement_=document.createElement("input");this.inputElement_.setAttribute("type","checkbox");this.inputElement_.checked=initialInputValue;this.inputElement_.addEventListener("change",this.onToggleChange.bind(this));this.debugContainer_.appendChild(this.inputElement_)}onToggleChange(){this.debugLogsChangeHandler_.changeDebugLogsState(this.inputElement_.checked)}}